import datetime, re, sys

def add_business_days(start, n, holidays):
    # Validate n
    if type(n) is not int or n < 0:
        raise ValueError("n must be a non-negative integer")
    # Validate start format and date
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', start):
        raise ValueError("start must be 'YYYY-MM-DD'")
    try:
        start_date = datetime.date.fromisoformat(start)
    except ValueError:
        raise ValueError("start must be a valid date")
    # Validate each holiday
    for h in holidays:
        if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', h):
            raise ValueError("holidays must be 'YYYY-MM-DD' strings")
        try:
            datetime.date.fromisoformat(h)
        except ValueError:
            raise ValueError("holiday date must be valid")
    # If n == 0, return start unchanged
    if n == 0:
        return start
    # Convert holidays list to set of date objects for fast lookup
    holiday_set = {datetime.date.fromisoformat(h) for h in holidays}
    # Iterate forward day by day
    current = start_date + datetime.timedelta(days=1)
    counted = 0
    while counted < n:
        if current.weekday() < 5 and current not in holiday_set:
            counted += 1
        if counted == n:
            return current.isoformat()
        current += datetime.timedelta(days=1)

def run_tests():
    # Example 1
    assert add_business_days('2026-10-23', 1, []) == '2026-10-26'
    # Example 2
    assert add_business_days('2026-10-23', 1, ['2026-10-26']) == '2026-10-27'
    # Example 3
    assert add_business_days('2026-10-24', 0, []) == '2026-10-24'
    # Additional tests
    # Negative n raises
    try:
        add_business_days('2026-10-23', -1, [])
        assert False, "should raise for negative n"
    except ValueError:
        pass
    # Non-int n (float) raises
    try:
        add_business_days('2026-10-23', 1.5, [])
        assert False, "should raise for non-int n"
    except ValueError:
        pass
    # Boolean n raises (bool is not int)
    try:
        add_business_days('2026-10-23', True, [])
        assert False, "should raise for bool n"
    except ValueError:
        pass
    # Invalid start format raises
    try:
        add_business_days('2026-13-01', 1, [])
        assert False, "should raise for invalid start format"
    except ValueError:
        pass
    # Invalid holiday format raises
    try:
        add_business_days('2026-10-23', 1, ['2026-13-01'])
        assert False, "should raise for invalid holiday format"
    except ValueError:
        pass
    # Invalid date (e.g., 2026-02-30) raises
    try:
        add_business_days('2026-02-30', 1, [])
        assert False, "should raise for invalid date"
    except ValueError:
        pass
    # Start is a weekend, n=1, no holidays -> should go to next Monday
    assert add_business_days('2026-10-24', 1, []) == '2026-10-26'
    # Start is a holiday, n=1, no other holidays -> next business day is Tuesday
    assert add_business_days('2026-10-26', 1, ['2026-10-26']) == '2026-10-27'
    # Counting multiple business days
    # start Fri 23, next business day is Mon 26 (1), Tue 27 (2), Wed 28 (3) => '2026-10-28'
    assert add_business_days('2026-10-23', 3, []) == '2026-10-28'
    # Holiday that falls on a weekend should not affect counting beyond normal weekend skip
    assert add_business_days('2026-10-23', 1, ['2026-10-25']) == '2026-10-26'  # Friday, next business day is Monday 26; holiday on Thu 25 irrelevant
    # Simple Monday start, n=1 => next business day Tuesday
    assert add_business_days('2026-10-26', 1, []) == '2026-10-27'
    # Ensure that when n is 0, start unchanged even if weekend
    assert add_business_days('2026-10-24', 0, []) == '2026-10-24'
    # Ensure that when start itself is a holiday but n>0, it still counts forward correctly
    assert add_business_days('2026-10-26', 1, ['2026-10-26']) == '2026-10-27'
    print("ALL TESTS PASSED")

if __name__ == "__main__":
    run_tests()

